import express, { Request, Response } from 'express';
import crypto from 'crypto';
import { Pool } from 'pg';

const app = express();
app.use(express.json());

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

const DISCOUNT_SERVICE_URL = process.env.DISCOUNT_SERVICE_URL || 'http://discount-svc:3001';
const PAYMENT_HMAC_SECRET = process.env.PAYMENT_HMAC_SECRET!;
const MAX_DISCOUNT_PERCENT = parseInt(process.env.MAX_DISCOUNT_PERCENT || '50', 10);
const CURRENCY_PRECISION = parseInt(process.env.CURRENCY_PRECISION || '2', 10);

interface CartItem {
  productId: string;
  quantity: number;
  unitPrice: number;
}

interface DiscountResponse {
  discountPercent: number;
  appliesTo: string[];
  stackable: boolean;
}

function computeItemTotal(item: CartItem): number {
  return Math.round(item.unitPrice * item.quantity * Math.pow(10, CURRENCY_PRECISION)) / Math.pow(10, CURRENCY_PRECISION);
}

function applyDiscount(amount: number, discountPercent: number): number {
  const factor = (100 - discountPercent) / 100;
  return Math.round(amount * factor * Math.pow(10, CURRENCY_PRECISION)) / Math.pow(10, CURRENCY_PRECISION);
}

function validateDiscountBounds(discountPercent: number): number {
  if (discountPercent < 0) return 0;
  if (discountPercent > MAX_DISCOUNT_PERCENT) return MAX_DISCOUNT_PERCENT;
  return discountPercent;
}

async function fetchDiscounts(userId: string, cartItems: CartItem[]): Promise<DiscountResponse[]> {
  const response = await fetch(`${DISCOUNT_SERVICE_URL}/api/discounts`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ userId, productIds: cartItems.map(i => i.productId) })
  });
  if (!response.ok) return [];
  return response.json();
}

function computeOrderTotal(cartItems: CartItem[], discounts: DiscountResponse[]): number {
  let total = 0;

  for (const item of cartItems) {
    let itemTotal = computeItemTotal(item);
    let appliedDiscounts: number[] = [];

    for (const discount of discounts) {
      if (discount.appliesTo.includes(item.productId) || discount.appliesTo.includes('*')) {
        const bounded = validateDiscountBounds(discount.discountPercent);
        appliedDiscounts.push(bounded);
      }
    }

    if (appliedDiscounts.length > 0) {
      // Apply discounts: if stackable, combine additively (capped); otherwise take best
      const hasStackable = discounts.some(d => d.stackable);
      if (hasStackable) {
        // Additive combination with cap at MAX_DISCOUNT_PERCENT
        const combinedDiscount = Math.min(appliedDiscounts.reduce((a, b) => a + b, 0), MAX_DISCOUNT_PERCENT);
        itemTotal = applyDiscount(itemTotal, combinedDiscount);
      } else {
        const bestDiscount = Math.max(...appliedDiscounts);
        itemTotal = applyDiscount(itemTotal, bestDiscount);
      }
    }

    total += itemTotal;
  }

  return Math.round(total * Math.pow(10, CURRENCY_PRECISION)) / Math.pow(10, CURRENCY_PRECISION);
}

function signPaymentRequest(orderId: string, amount: number, userId: string): string {
  const payload = `${orderId}|${amount}|${userId}`;
  return crypto.createHmac('sha256', PAYMENT_HMAC_SECRET).update(payload).digest('hex');
}

// Constant-time comparison that is safe against length mismatches / invalid input.
function safeSignatureCompare(provided: unknown, expected: string): boolean {
  if (typeof provided !== 'string' || !/^[0-9a-fA-F]+$/.test(provided)) {
    return false;
  }
  const expectedBuf = Buffer.from(expected, 'hex');
  const providedBuf = Buffer.from(provided, 'hex');
  if (providedBuf.length !== expectedBuf.length) {
    return false;
  }
  return crypto.timingSafeEqual(providedBuf, expectedBuf);
}

app.post('/api/checkout', async (req: Request, res: Response) => {
  const { userId, cartItems, orderId } = req.body;

  if (!userId || !cartItems || !orderId || !Array.isArray(cartItems)) {
    return res.status(400).json({ error: 'Invalid request' });
  }

  for (const item of cartItems) {
    if (!item.productId || typeof item.quantity !== 'number' || typeof item.unitPrice !== 'number') {
      return res.status(400).json({ error: 'Invalid cart item' });
    }
    if (item.quantity <= 0 || item.unitPrice <= 0) {
      return res.status(400).json({ error: 'Invalid cart item values' });
    }
  }

  // Verify prices against catalog
  const priceCheck = await pool.query(
    'SELECT product_id, price FROM products WHERE product_id = ANY($1)',
    [cartItems.map((i: CartItem) => i.productId)]
  );
  const catalogPrices = new Map(priceCheck.rows.map((r: any) => [r.product_id, parseFloat(r.price)]));

  for (const item of cartItems) {
    const catalogPrice = catalogPrices.get(item.productId);
    if (catalogPrice === undefined || Math.abs(catalogPrice - item.unitPrice) > 0.001) {
      return res.status(400).json({ error: 'Price mismatch' });
    }
  }

  const discounts = await fetchDiscounts(userId, cartItems);
  const orderTotal = computeOrderTotal(cartItems, discounts);

  // Ensure total is positive
  const finalAmount = Math.max(orderTotal, 0);

  const signature = signPaymentRequest(orderId, finalAmount, userId);

  await pool.query(
    'INSERT INTO orders (order_id, user_id, amount, status, created_at) VALUES ($1, $2, $3, $4, NOW())',
    [orderId, userId, finalAmount, 'pending']
  );

  return res.json({
    orderId,
    amount: finalAmount,
    signature,
    paymentUrl: `/api/pay?order=${orderId}&sig=${signature}`
  });
});

app.post('/api/pay', async (req: Request, res: Response) => {
  const { orderId, signature, userId } = req.body;

  if (!orderId || !userId || typeof signature !== 'string') {
    return res.status(400).json({ error: 'Invalid request' });
  }

  const order = await pool.query('SELECT * FROM orders WHERE order_id = $1 AND user_id = $2', [orderId, userId]);
  if (order.rows.length === 0) {
    return res.status(404).json({ error: 'Order not found' });
  }

  const expectedSig = signPaymentRequest(orderId, order.rows[0].amount, userId);
  if (!safeSignatureCompare(signature, expectedSig)) {
    return res.status(403).json({ error: 'Invalid signature' });
  }

  await pool.query('UPDATE orders SET status = $1 WHERE order_id = $2', ['completed', orderId]);
  return res.json({ status: 'payment_successful', amount: order.rows[0].amount });
});

export default app;
